/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=dealProduct, operation=remove
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Remove a product from a deal */
export type PipedriveV2DealProductRemoveParams = {
  resource: 'dealProduct';
  operation: 'remove';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the deal whose product to remove
 * @default 0
 */
    dealId?: number | Expression<number>;
/**
 * ID of the deal-product (the ID of the product attached to the deal, not the product ID itself)
 * @default 0
 */
    productAttachmentId?: number | Expression<number>;
};

export type PipedriveV2DealProductRemoveNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  credentials?: Credentials;
  config: NodeConfig<PipedriveV2DealProductRemoveParams>;
};